102	function listDocs() {
103	  const cwd = process.cwd();
104	  const items = DOC_FILENAMES.filter((file) => fs.existsSync(path.join(cwd, file)));
105	  if (!items.length) {
106	    log.info('No documentation files detected in current directory.', { cwd });
107	    return;
108	  }
109	  log.info('Documentation files found:', { files: items });
110	  items.forEach((file) => console.log(`  - ${file}`));
111	}
