547	async function handleCompatibilityOptions(options: GenerateOptions & { listDocs?: boolean; clean?: boolean; exportPdf?: boolean; update?: boolean; setup?: boolean; showConfig?: boolean }) {
548	  if (options.update) {
549	    checkForUpdates();
550	    if (!options.scan && !options.setup && !options.listDocs && !options.clean) {
551	      return;
552	    }
553	  }
554	  if (options.setup) {
555	    await runSetupFlow(options.key, options.global);
556	    return;
557	  }
558	  if (options.listDocs) {
559	    listDocs();
560	    return;
561	  }
562	  if (options.clean) {
563	    cleanDocs();
564	    return;
565	  }
566	  const exportOnly =
567	    options.exportPdf &&
568	    !options.scan &&
569	    !options.ci &&
570	    !options.setup &&
571	    !options.listDocs &&
572	    !options.clean &&
573	    !options.update &&
574	    !options.showConfig &&
575	    !options.key;
576	  if (exportOnly) {
577	    exportDocsAsPdf();
578	    return;
579	  }
580	  const showConfigOnly =
581	    options.showConfig &&
582	    !options.scan &&
583	    !options.ci &&
584	    !options.setup &&
585	    !options.listDocs &&
586	    !options.clean &&
587	    !options.update &&
588	    !options.exportPdf &&
589	    !options.key;
590	  if (showConfigOnly) {
591	    showConfigStatus();
592	    return;
593	  }
594	  await runGenerateFlow(options);
595	}
