function parseThresholds(thresholdStrings?: string[]): Record<string, number> | null {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return null;
  }

  const thresholds: Record<string, number> = {};
  const validMetrics = ['exact_match', 'toxicity', 'length_variance'];

  for (const thresholdStr of thresholdStrings) {
    const match = thresholdStr.match(/^([a-z_]+)=([0-9]*\.?[0-9]+)$/);
    if (!match) {
      log.error(`Invalid threshold format: ${thresholdStr}`);
      log.error('Expected format: <metric>=<number>');
      log.error(`Valid metrics: ${validMetrics.join(', ')}`);
      process.exit(2);
    }

    const [, metricId, valueStr] = match;
    const value = Number.parseFloat(valueStr);

    if (Number.isNaN(value) || value < 0 || value > 1) {
      log.error(`Invalid threshold value: ${valueStr}`);
      log.error('Threshold must be a number between 0 and 1');
      process.exit(2);
    }

    if (!validMetrics.includes(metricId)) {
      log.error(`Unknown metric: ${metricId}`);
      log.error(`Valid metrics: ${validMetrics.join(', ')}`);
      process.exit(2);
    }

    thresholds[metricId] = value;
  }

  return thresholds;
}

