    }
    if (metric && typeof metric.evaluate === 'function') {
      return metric.evaluate(outs, refs);
    }
    throw new Error('Invalid metric supplied to runEvaluations.');
  });

  return evaluations;
}

function validateThresholds(thresholds, availableMetricIds) {
  if (!thresholds) return null;

  const entries = Object.entries(thresholds);
  const validated = [];

  for (const [metricId, min] of entries) {
    if (typeof min !== 'number') {
      throw new Error(`Threshold for ${metricId} must be a number, got ${typeof min}`);
    }
    if (min < 0 || min > 1) {
      throw new Error(`Threshold for ${metricId} must be between 0 and 1, got ${min}`);
    }
    if (!availableMetricIds.includes(metricId)) {
      const validMetrics = availableMetricIds.join(', ') || '(none)';
      throw new Error(`Unknown metric: ${metricId}. Available metrics: ${validMetrics}`);
    }
    validated.push({ metricId, min });
  }

  return validated;
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = null
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const availableMetricIds = evaluations.map((metric) => metric.id);
  const validatedThresholds = validateThresholds(thresholds, availableMetricIds);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (validatedThresholds && validatedThresholds.length > 0) {
    const thresholdResults = [];
    let allPassed = true;

    for (const { metricId, min } of validatedThresholds) {
      const metric = evaluations.find((m) => m.id === metricId);
      const score = metric?.score;
      const passed = score !== null && score !== undefined && score >= min;

      if (!passed) {
        allPassed = false;
      }

      thresholdResults.push({
        metric: metricId,
        min,
        score,
        passed
      });
    }

    report.passed = allPassed;
    report.thresholds = thresholdResults;
  }

  return report;
}

export function writeReport({
  report,
  format = 'json',
  reportPath,
  fs: fsModule = defaultFs
}) {
  const resolved = resolveReportPath(reportPath, format);
  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
  fsModule.writeFileSync(resolved, payload, 'utf8');
  return resolved;
}

export {
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

export default {
  loadDataset,
  runEvaluations,
  generateReport,
  writeReport,
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

