  .option('--format <format>', 'Report format (json or markdown)', 'json')
  .option('--threshold <metric=min>', 'Metric threshold in format metric=value (e.g., exact_match=0.9). Can be specified multiple times.', (value, previous) => {
    return previous ? [...previous, value] : [value];
  })
  .action((options: EvalOptions) => {
    runEvalCommand(options);
  });

