  it('generates and writes report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.metadata.totalSamples).toBe(1);

    const dir = createTempDir();
    const jsonPath = writeReport({
      report,
      format: 'json',
      reportPath: path.join(dir, 'report.json')
    });
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });

  it('validates thresholds and reports passed/failed status', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'friendly world'],
      references: ['hello', 'friendly world']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: {
        exact_match: 0.5
      }
    });

    expect(report.passed).toBe(true);
    expect(report.thresholds).toHaveLength(1);
    expect(report.thresholds[0].metric).toBe('exact_match');
    expect(report.thresholds[0].passed).toBe(true);
  });

  it('marks threshold as failed when score is below minimum', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'different'],
      references: ['hello', 'world']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: {
        exact_match: 0.9
      }
    });

    expect(report.passed).toBe(false);
    expect(report.thresholds[0].passed).toBe(false);
  });

  it('fails threshold when metric has no score', () => {
    const evaluations = runEvaluations({
      outputs: [],
      references: []
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: {
        exact_match: 0.5
      }
    });

    expect(report.passed).toBe(false);
    expect(report.thresholds[0].passed).toBe(false);
    expect(report.thresholds[0].score).toBeNull();
  });

  it('rejects unknown metric in threshold', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    expect(() => {
      generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        referencesPath: '/tmp/refs.json',
        generatedAt: '2024-01-01T00:00:00.000Z',
        thresholds: {
          unknown_metric: 0.5
        }
      });
    }).toThrow('Unknown metric: unknown_metric');
  });

  it('rejects out-of-range threshold value', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    expect(() => {
      generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        referencesPath: '/tmp/refs.json',
        generatedAt: '2024-01-01T00:00:00.000Z',
        thresholds: {
          exact_match: 1.5
        }
      });
    }).toThrow('Threshold for exact_match must be between 0 and 1');
  });
});

